var outfits=[{"id": "rl-chilly-f35-day-run-20261025-01", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "f", "age": "35", "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/01/editorial.jpg", "deck": {"ko": "슬레이트 블루 셸에 차콜 레이어를 겹쳐 가벼운 비 속 러닝을 준비한다.", "en": "Charcoal layers under a slate-blue shell, ready for a light-rain run.", "de": "Anthrazitfarbene Lagen unter einer schieferblauen Shell, bereit für einen Lauf im Nieselregen."}, "items": ["rl-chilly-f35-day-run-20261025-01.01-outer", "rl-chilly-f35-day-run-20261025-01.02-top", "rl-chilly-f35-day-run-20261025-01.03-bottom", "rl-chilly-f35-day-run-20261025-01.04-socks", "rl-chilly-f35-day-run-20261025-01.05-shoes"], "article": {"title": "SLATE BLUE SIDESTEP", "intro": {"ko": "가벼운 셸과 집넥 이너, 긴 타이츠로 쌀쌀한 날의 러닝 레이어를 구성했다. 소매와 종아리의 반사 디테일이 차분한 색조에 선명한 포인트를 더한다.", "en": "A light hooded shell over a zip-neck layer and full-length tights makes a running kit for a chilly, drizzly day. Small reflective marks on the sleeve and lower leg add a bright line to the muted colours.", "de": "Eine leichte Kapuzen-Shell über einem Shirt mit Reißverschlusskragen und lange Tights ergeben ein Laufoutfit für einen kühlen, nieseligen Tag. Kleine Reflexmarken an Ärmel und Unterschenkel setzen eine helle Linie in die gedeckten Farben."}, "pull": "ONE QUICK STEP AROUND THE PUDDLE.", "tip": {"ko": "달리며 더워지면 셸 지퍼를 조금 열어 환기하세요.", "en": "Once you warm up, open the shell zip a little to let air in.", "de": "Sobald dir warm wird, den Reißverschluss der Shell etwas öffnen und Luft hereinlassen."}}, "hero": "rl-chilly-f35-day-run-20261025-01.01-outer"}, {"id": "rl-chilly-f35-day-run-20261025-02", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "f", "age": "35", "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/02/editorial.jpg", "deck": {"ko": "세이지 셸과 아이보리 이너가 젖은 거리 위에서 부드럽게 어우러진다.", "en": "A sage shell and an ivory layer sit softly together on the wet street.", "de": "Eine salbeigrüne Shell und eine elfenbeinfarbene Lage verbinden sich sanft auf der nassen Straße."}, "items": ["rl-chilly-f35-day-run-20261025-02.01-outer", "rl-chilly-f35-day-run-20261025-02.02-top", "rl-chilly-f35-day-run-20261025-02.03-bottom", "rl-chilly-f35-day-run-20261025-02.04-socks", "rl-chilly-f35-day-run-20261025-02.05-shoes"], "article": {"title": "LACES FIRST", "intro": {"ko": "기능성 레이어를 세이지와 아이보리로 가볍게 풀어낸 러닝 룩. 차콜 타이츠와 밝은 러닝화가 단정한 균형을 만든다.", "en": "Technical running layers in sage and ivory, kept light and easy. Charcoal tights and pale running shoes give the look a neat balance.", "de": "Funktionelle Laufschichten in Salbei und Elfenbein, leicht und unkompliziert. Anthrazitfarbene Tights und helle Laufschuhe bringen den Look in eine ruhige Balance."}, "pull": "TIE IT TIGHT, THEN GO AGAIN.", "tip": {"ko": "다시 출발하기 전 신발 끈과 젖은 노면을 확인하세요.", "en": "Before you set off again, check your laces and the wet ground ahead.", "de": "Bevor es weitergeht, Schnürsenkel und den nassen Boden vor dir prüfen."}}, "hero": "rl-chilly-f35-day-run-20261025-02.01-outer"}, {"id": "rl-chilly-f35-day-run-20261025-03", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "f", "age": "35", "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/03/editorial.jpg", "deck": {"ko": "코발트 셸과 은백색 반사 지퍼로 흐린 날에도 또렷한 러닝 룩.", "en": "A cobalt shell and a silver-white reflective zip keep the run crisp on a grey day.", "de": "Eine kobaltblaue Shell mit silberweißem Reflex-Reißverschluss hält den Lauf an einem grauen Tag klar."}, "items": ["rl-chilly-f35-day-run-20261025-03.01-outer", "rl-chilly-f35-day-run-20261025-03.02-top", "rl-chilly-f35-day-run-20261025-03.03-bottom"], "article": {"title": "COBALT, HOOD UP", "intro": {"ko": "선명한 코발트 셸 안에 블랙 하이넥 이너를 겹쳤다. 손목을 감싸는 소매와 타이츠로 활동적인 실루엣을 이어간다.", "en": "A black high-neck layer sits inside a vivid cobalt shell. Sleeves that wrap the wrist and fitted tights carry the active silhouette all the way down.", "de": "In einer leuchtend kobaltblauen Shell steckt eine schwarze Lage mit hohem Kragen. Ärmel, die das Handgelenk umschließen, und eng anliegende Tights führen die sportliche Silhouette bis nach unten weiter."}, "pull": "ONE HAND ON THE HOOD, EYES ON THE ROAD.", "tip": {"ko": "바람에 후드가 흔들리면 시야를 가리지 않도록 정리하세요.", "en": "If the wind catches your hood, tuck it back so it doesn't cover your view.", "de": "Wenn der Wind die Kapuze erfasst, sie zurechtrücken, damit sie die Sicht nicht verdeckt."}}, "hero": "rl-chilly-f35-day-run-20261025-03.01-outer"}, {"id": "rl-chilly-f35-day-run-20261025-04", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "f", "age": "35", "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/04/editorial.jpg", "deck": {"ko": "웜 그레이 셸 아래 버건디를 더해 러닝 레이어에 깊이를 준다.", "en": "Burgundy under a warm grey shell gives the running layers depth.", "de": "Bordeaux unter einer warmgrauen Shell gibt den Laufschichten Tiefe."}, "items": ["rl-chilly-f35-day-run-20261025-04.01-outer", "rl-chilly-f35-day-run-20261025-04.02-top", "rl-chilly-f35-day-run-20261025-04.03-bottom", "rl-chilly-f35-day-run-20261025-04.04-watch", "rl-chilly-f35-day-run-20261025-04.05-shoes"], "article": {"title": "A BURGUNDY PACE CHECK", "intro": {"ko": "웜 그레이와 버건디, 에스프레소 타이츠를 조합한 차분한 러닝 룩. 심플한 스포츠 워치와 그레이 러닝화로 실용성을 더했다.", "en": "Warm grey, burgundy and espresso tights make a calm running look. A simple sports watch and grey running shoes add the practical part.", "de": "Warmgrau, Bordeaux und espressobraune Tights ergeben einen ruhigen Lauflook. Eine schlichte Sportuhr und graue Laufschuhe ergänzen das Praktische."}, "pull": "A GLANCE AT THE WRIST, THEN BACK TO THE RUN.", "tip": {"ko": "워치를 확인할 때는 안전한 곳에 잠시 멈추세요.", "en": "Step somewhere safe and pause briefly before checking your watch.", "de": "Zum Blick auf die Uhr kurz an einer sicheren Stelle anhalten."}}, "hero": "rl-chilly-f35-day-run-20261025-04.02-top"}, {"id": "rl-chilly-f35-day-run-20261025-05", "bands": ["chilly"], "sky": "rain", "rain": "light", "style": "run", "gender": "f", "age": "35", "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/05/editorial.jpg", "deck": {"ko": "코럴 셸과 그래파이트 레이어로 빗속 러닝에 경쾌한 색을 더한다.", "en": "A coral shell and graphite layers bring a lively colour to a run in the rain.", "de": "Eine korallenrote Shell und graphitgraue Lagen bringen eine lebhafte Farbe in den Lauf im Regen."}, "items": ["rl-chilly-f35-day-run-20261025-05.01-outer", "rl-chilly-f35-day-run-20261025-05.02-top", "rl-chilly-f35-day-run-20261025-05.03-bottom", "rl-chilly-f35-day-run-20261025-05.04-socks", "rl-chilly-f35-day-run-20261025-05.05-shoes"], "article": {"title": "OFF AGAIN IN CORAL", "intro": {"ko": "코럴 셸의 등과 소매에 자리한 반사 디테일이 움직임을 강조한다. 블랙 타이츠와 다크 그레이 러닝화로 선명한 상의를 받쳐준다.", "en": "Reflective details on the back and sleeves of the coral shell follow every movement. Black tights and dark grey running shoes hold up the bright top half.", "de": "Reflexdetails an Rücken und Ärmeln der korallenroten Shell betonen jede Bewegung. Schwarze Tights und dunkelgraue Laufschuhe tragen die leuchtende obere Hälfte."}, "pull": "SHORTER STEPS ON THE WET KERB.", "tip": {"ko": "젖은 연석에서는 보폭을 줄이고 천천히 내려오세요.", "en": "On a wet kerb, shorten your stride and step down slowly.", "de": "An einer nassen Bordsteinkante kürzere Schritte machen und langsam heruntersteigen."}}, "hero": "rl-chilly-f35-day-run-20261025-05.01-outer"}];
var items={"rl-chilly-f35-day-run-20261025-01.01-outer": {"id": "rl-chilly-f35-day-run-20261025-01.01-outer", "cat": "outer", "name": {"ko": "슬레이트 블루 러닝 셸", "en": "Slate-blue hooded running shell", "de": "Schieferblaue Lauf-Shell mit Kapuze"}, "note": {"ko": "지퍼를 가슴 중간까지만 올려 차콜 이너의 칼라가 보이게 입어요. 위팔의 은색 반사 줄과 주머니 가장자리 파이핑이 차분한 슬레이트 블루에 선을 그어 줘요.", "en": "Zip it only to mid-chest so the charcoal collar underneath shows; the silver strip on the upper arm and the piping along the pockets draw a clean line across the muted slate blue.", "de": "Nur bis zur Brustmitte schließen, damit der anthrazitfarbene Kragen darunter sichtbar bleibt; der Silberstreifen am Oberarm und die Paspel an den Taschen ziehen eine klare Linie über das gedeckte Schieferblau."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/01/products/01-outer.webp", "alt": "슬레이트 블루 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-01.02-top": {"id": "rl-chilly-f35-day-run-20261025-01.02-top", "cat": "top", "name": {"ko": "차콜 집넥 이너", "en": "Charcoal zip-neck running layer", "de": "Anthrazitfarbenes Laufshirt mit Reißverschlusskragen"}, "note": {"ko": "몸에 붙는 핏이라 셸 안에서 들뜨지 않아요. 스탠드 칼라를 끝까지 올려 목을 덮고, 몸이 데워지면 짧은 지퍼를 내려 열을 빼요.", "en": "The close fit lies flat under the shell. Zip the stand collar all the way up to cover the neck at the start, then lower the short zip once you have warmed up.", "de": "Der enge Schnitt liegt unter der Shell flach an. Zu Beginn den Stehkragen ganz hochziehen und den kurzen Reißverschluss öffnen, sobald dir warm ist."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/01/products/02-top.webp", "alt": "차콜 집넥 이너 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-01.03-bottom": {"id": "rl-chilly-f35-day-run-20261025-01.03-bottom", "cat": "bottom", "name": {"ko": "차콜 러닝 타이츠", "en": "Charcoal full-length running tights", "de": "Anthrazitfarbene lange Lauftights"}, "note": {"ko": "허리를 셸 밑단 아래로 깔끔하게 넣어 상하의 차콜 톤을 이어요. 정강이 아래 가는 은색 표시가 발걸음마다 살짝 보이도록 밑단은 접지 말고 발목까지 내려 입어요.", "en": "Tuck the waistband neatly under the shell hem to carry the charcoal from top to bottom, and leave the hems down at the ankle so the thin silver mark on the lower shin shows with every stride.", "de": "Den Bund ordentlich unter den Jackensaum führen, damit sich das Anthrazit von oben nach unten fortsetzt; die Säume bis zum Knöchel lassen, so blitzt die feine Silbermarke am Schienbein bei jedem Schritt auf."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/01/products/03-bottom.webp", "alt": "차콜 러닝 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-01.04-socks": {"id": "rl-chilly-f35-day-run-20261025-01.04-socks", "cat": "socks", "name": {"ko": "라이트 그레이 러닝 양말", "en": "Light grey ribbed crew running socks", "de": "Hellgraue gerippte Laufsocken in Crew-Länge"}, "note": {"ko": "크루 길이를 타이츠 밑단 위로 끌어올려 발목에 틈이 생기지 않게 해요. 라이트 그레이가 실버 러닝화와 자연스럽게 이어져요.", "en": "Pull the crew length up over the tights hem so no gap opens at the ankle; the light grey runs straight into the silver shoes.", "de": "Die Crew-Länge über den Tightssaum ziehen, damit am Knöchel keine Lücke entsteht; das Hellgrau geht nahtlos in die silbernen Schuhe über."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/01/products/04-socks.webp", "alt": "라이트 그레이 러닝 양말 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-01.05-shoes": {"id": "rl-chilly-f35-day-run-20261025-01.05-shoes", "cat": "shoes", "name": {"ko": "실버 그레이 러닝화", "en": "Silver-grey mesh running shoes", "de": "Silbergraue Laufschuhe aus Mesh"}, "note": {"ko": "그레이 끈을 발등에 맞게 고르게 조이고 매듭은 짧게 정리해요. 실버 메시와 밝은 미드솔이 젖은 보도 위에서 룩의 가장 밝은 부분이 돼요.", "en": "Tighten the grey laces evenly over the instep and keep the bow short; the silver mesh and pale midsole become the brightest part of the look on a wet pavement.", "de": "Die grauen Schnürsenkel gleichmäßig über dem Spann anziehen und die Schleife kurz halten; silbernes Mesh und helle Mittelsohle sind auf nassem Pflaster der hellste Teil des Looks."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/01/products/05-shoes.webp", "alt": "실버 그레이 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-02.01-outer": {"id": "rl-chilly-f35-day-run-20261025-02.01-outer", "cat": "outer", "name": {"ko": "세이지 러닝 셸", "en": "Sage green hooded running shell", "de": "Salbeigrüne Lauf-Shell mit Kapuze"}, "note": {"ko": "지퍼를 반쯤 열어 아이보리 칼라가 세이지 사이로 드러나게 입어요. 어깨의 은백색 반사 줄이 부드러운 녹색에 또렷한 선을 더하고, 고무 소매단이 손목에서 고정돼요.", "en": "Wear it half unzipped so the ivory collar shows against the sage; the silver-white strips at the shoulders add a crisp line to the soft green, and the elastic cuffs stay put at the wrist.", "de": "Halb geöffnet tragen, damit der elfenbeinfarbene Kragen am Salbeigrün hervorschaut; die silberweißen Streifen an den Schultern setzen eine klare Linie, und die elastischen Bündchen sitzen fest am Handgelenk."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/02/products/01-outer.webp", "alt": "세이지 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-02.02-top": {"id": "rl-chilly-f35-day-run-20261025-02.02-top", "cat": "top", "name": {"ko": "아이보리 집넥 이너", "en": "Ivory zip-neck running layer", "de": "Elfenbeinfarbenes Laufshirt mit Reißverschlusskragen"}, "note": {"ko": "하이 칼라를 세워 셸 안에서 목선을 밝게 잡아 줘요. 아이보리 한 겹이 세이지와 차콜 사이의 무게를 덜어 줘요.", "en": "Stand the high collar up inside the shell to frame the neckline in a light tone; one ivory layer takes the weight out of the sage and charcoal.", "de": "Den hohen Kragen in der Shell aufstellen, so rahmt ein heller Ton den Halsausschnitt; eine elfenbeinfarbene Lage nimmt Salbei und Anthrazit die Schwere."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/02/products/02-top.webp", "alt": "아이보리 집넥 이너 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-02.03-bottom": {"id": "rl-chilly-f35-day-run-20261025-02.03-bottom", "cat": "bottom", "name": {"ko": "차콜 패널 타이츠", "en": "Charcoal panelled running tights", "de": "Anthrazitfarbene Lauftights mit Teilungsnähten"}, "note": {"ko": "무릎을 따라 곡선으로 나뉜 패널이 다리 라인을 정리해 줘요. 밑단은 발목까지 곧게 내려 양말 위에 겹쳐 입어요.", "en": "The curved panels around the knee tidy the line of the leg; let the hems fall straight to the ankle and sit over the socks.", "de": "Die geschwungenen Teilungsnähte am Knie ordnen die Beinlinie; die Säume gerade bis zum Knöchel fallen lassen und über den Socken tragen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/02/products/03-bottom.webp", "alt": "차콜 패널 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-02.04-socks": {"id": "rl-chilly-f35-day-run-20261025-02.04-socks", "cat": "socks", "name": {"ko": "그레이 러닝 양말", "en": "Heather grey ribbed crew running socks", "de": "Grau melierte gerippte Laufsocken in Crew-Länge"}, "note": {"ko": "타이츠 밑단 아래로 리브가 한 뼘쯤 보이게 신어요. 헤더 그레이가 차콜과 오프화이트 신발 사이를 부드럽게 이어 줘요.", "en": "Let a hand's width of the rib show below the tights; the heather grey bridges the charcoal and the off-white shoes.", "de": "Unter den Tights etwa eine Handbreit Rippe zeigen; das melierte Grau verbindet Anthrazit und die gebrochen weißen Schuhe."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/02/products/04-socks.webp", "alt": "그레이 러닝 양말 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-02.05-shoes": {"id": "rl-chilly-f35-day-run-20261025-02.05-shoes", "cat": "shoes", "name": {"ko": "오프화이트 러닝화", "en": "Off-white mesh running shoes", "de": "Gebrochen weiße Laufschuhe aus Mesh"}, "note": {"ko": "출발 전에 흰 끈을 발등부터 차례로 당겨 고르게 조이고, 매듭을 두 번 묶어 풀리지 않게 해요. 검은 앞코와 밑창이 밝은 신발의 윤곽을 잡아 줘요.", "en": "Before you set off, pull the white laces snug from the instep upward and double-knot them; the black toe and outsole outline the pale shoe.", "de": "Vor dem Start die weißen Schnürsenkel vom Spann aufwärts gleichmäßig anziehen und doppelt knoten; schwarze Spitze und Laufsohle zeichnen die Kontur des hellen Schuhs."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/02/products/05-shoes.webp", "alt": "오프화이트 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-03.01-outer": {"id": "rl-chilly-f35-day-run-20261025-03.01-outer", "cat": "outer", "name": {"ko": "코발트 리플렉티브 셸", "en": "Cobalt hooded reflective running shell", "de": "Kobaltblaue reflektierende Lauf-Shell mit Kapuze"}, "note": {"ko": "후드를 쓸 때는 앞 지퍼를 끝까지 올려 은색 테두리가 얼굴 아래까지 한 줄로 이어지게 해요. 사선 지퍼 주머니의 은백색 라인이 코발트 위에서 또렷이 빛나요.", "en": "With the hood up, zip right to the top so the silver edging runs in one line up to the chin; the silver-white trim on the diagonal zip pockets stands out sharply on the cobalt.", "de": "Mit aufgesetzter Kapuze ganz hochziehen, damit die Silberkante in einer Linie bis unters Kinn läuft; die silberweiße Blende an den schrägen Reißverschlusstaschen leuchtet klar auf dem Kobaltblau."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/03/products/01-outer.webp", "alt": "코발트 리플렉티브 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-03.02-top": {"id": "rl-chilly-f35-day-run-20261025-03.02-top", "cat": "top", "name": {"ko": "블랙 하이넥 이너", "en": "Black high-neck running layer with thumbholes", "de": "Schwarzes Laufshirt mit hohem Kragen und Daumenlöchern"}, "note": {"ko": "엄지 구멍에 손가락을 끼워 소매가 손등까지 덮이게 하면 셸 소매단 밖으로 블랙 라인이 깔끔하게 나와요. 하이넥이 코발트 칼라 안을 어둡게 채워 줘요.", "en": "Hook your thumbs through the thumbholes so the sleeves cover the back of the hand and a clean black line shows beyond the shell cuffs; the high neck fills the cobalt collar with a dark base.", "de": "Die Daumen durch die Daumenlöcher stecken, so bedecken die Ärmel den Handrücken und zeigen unter den Shell-Bündchen eine klare schwarze Linie; der hohe Kragen füllt das kobaltblaue Revers mit dunklem Grund."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/03/products/02-top.webp", "alt": "블랙 하이넥 이너 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-03.03-bottom": {"id": "rl-chilly-f35-day-run-20261025-03.03-bottom", "cat": "bottom", "name": {"ko": "블랙 러닝 타이츠", "en": "Black running tights", "de": "Schwarze Lauftights"}, "note": {"ko": "허벅지를 따라 곡선 솔기가 지나가는 매트 블랙이라 선명한 코발트를 차분하게 받쳐 줘요. 셸 밑단이 엉덩이 위에 오도록 허리를 높게 올려 입어요.", "en": "Matte black with curved seams along the thigh, they let the bright cobalt do the talking; wear the waist high so the shell hem sits just above the hips.", "de": "Mattes Schwarz mit geschwungenen Nähten am Oberschenkel überlässt dem leuchtenden Kobalt die Bühne; den Bund hoch tragen, damit der Jackensaum knapp über der Hüfte sitzt."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/03/products/03-bottom.webp", "alt": "블랙 러닝 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-04.01-outer": {"id": "rl-chilly-f35-day-run-20261025-04.01-outer", "cat": "outer", "name": {"ko": "웜 그레이 러닝 셸", "en": "Warm grey hooded running shell", "de": "Warmgraue Lauf-Shell mit Kapuze"}, "note": {"ko": "검은 지퍼를 가슴 아래까지 내려 버건디 크루넥이 V자로 보이게 입어요. 위팔의 사각 반사 패치와 가슴의 가는 반사 포인트가 웜 그레이를 단조롭지 않게 해 줘요.", "en": "Unzip the black zip to below the chest so the burgundy crew neck shows in a V; the square reflective patches on the upper arms and the slim chest accent keep the warm grey from looking flat.", "de": "Den schwarzen Reißverschluss bis unter die Brust öffnen, damit der bordeauxfarbene Rundhals als V sichtbar wird; die eckigen Reflexpatches an den Oberarmen und der schmale Akzent auf der Brust beleben das Warmgrau."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/04/products/01-outer.webp", "alt": "웜 그레이 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-04.02-top": {"id": "rl-chilly-f35-day-run-20261025-04.02-top", "cat": "top", "name": {"ko": "버건디 롱슬리브", "en": "Burgundy crew-neck running long sleeve", "de": "Bordeauxfarbenes Laufshirt mit Rundhals und langen Ärmeln"}, "note": {"ko": "긴 소매를 셸 소매단 밖으로 손목까지 조금 끌어내리면 버건디가 시계 옆에서 한 번 더 보여요. 크루넥이라 셸 지퍼를 열어도 목선이 단정해요.", "en": "Draw the long sleeves a little past the shell cuffs so the burgundy shows again beside the watch; the crew neck keeps the neckline tidy even with the shell open.", "de": "Die langen Ärmel etwas über die Shell-Bündchen ziehen, damit das Bordeaux neben der Uhr noch einmal auftaucht; der Rundhals hält den Ausschnitt auch bei offener Shell ordentlich."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/04/products/02-top.webp", "alt": "버건디 롱슬리브 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-04.03-bottom": {"id": "rl-chilly-f35-day-run-20261025-04.03-bottom", "cat": "bottom", "name": {"ko": "에스프레소 타이츠", "en": "Espresso full-length running tights", "de": "Espressobraune lange Lauftights"}, "note": {"ko": "블랙 대신 짙은 에스프레소 브라운이라 웜 그레이·버건디와 같은 따뜻한 톤으로 이어져요. 허리와 허벅지 위쪽의 곡선 솔기가 보이도록 셸 밑단은 허리 위에서 끝나게 입어요.", "en": "Deep espresso brown instead of black keeps the whole look in warm tones with the grey and burgundy; let the shell end at the waist so the curved seams over the hips and upper thighs show.", "de": "Tiefes Espressobraun statt Schwarz hält den Look mit Grau und Bordeaux in warmen Tönen; die Shell an der Taille enden lassen, damit die geschwungenen Nähte an Hüfte und Oberschenkel zu sehen sind."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/04/products/03-bottom.webp", "alt": "에스프레소 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-04.04-watch": {"id": "rl-chilly-f35-day-run-20261025-04.04-watch", "cat": "watch", "name": {"ko": "블랙 스포츠 워치", "en": "Black sports watch", "de": "Schwarze Sportuhr"}, "note": {"ko": "버건디 소매단 바로 아래 손목뼈 위에 차서 셸 소매를 걷지 않고도 화면이 보이게 해요. 무광 블랙 실리콘 밴드는 출발 전에 손목에 꼭 맞게 조여요.", "en": "Wear it just below the burgundy cuff on the wrist bone so the face is visible without pushing back the shell sleeve; fasten the matte black silicone strap snugly before you set off.", "de": "Direkt unter dem bordeauxfarbenen Bündchen auf dem Handgelenkknochen tragen, so ist das Display sichtbar, ohne den Shell-Ärmel hochzuschieben; das matte schwarze Silikonarmband vor dem Start eng schließen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/04/products/04-watch.webp", "alt": "블랙 스포츠 워치 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-04.05-shoes": {"id": "rl-chilly-f35-day-run-20261025-04.05-shoes", "cat": "shoes", "name": {"ko": "그레이 러닝화", "en": "Grey mesh running shoes", "de": "Graue Laufschuhe aus Mesh"}, "note": {"ko": "그레이 메시와 오버레이가 셸의 웜 그레이와 같은 계열이라 위아래가 하나로 묶여요. 밝은 밑창이 어두운 타이츠 끝을 가볍게 마무리해요.", "en": "The grey mesh and overlays sit in the same family as the warm grey shell, tying top and bottom together; the pale sole finishes the dark tights lightly.", "de": "Graues Mesh und Overlays gehören zur selben Farbfamilie wie die warmgraue Shell und verbinden oben und unten; die helle Sohle schließt die dunklen Tights leicht ab."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/04/products/05-shoes.webp", "alt": "그레이 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-05.01-outer": {"id": "rl-chilly-f35-day-run-20261025-05.01-outer", "cat": "outer", "name": {"ko": "코럴 러닝 셸", "en": "Coral hooded running shell", "de": "Korallenrote Lauf-Shell mit Kapuze"}, "note": {"ko": "허리의 조임 밑단이 엉덩이 위에서 멈추게 입어 등의 은색 세로 줄과 팔꿈치 반사 줄이 달리는 동안 잘 보이게 해요. 코럴 한 가지만 밝게 두고 나머지는 어둡게 맞춰요.", "en": "Let the gathered hem stop just above the hips so the vertical silver strip on the back and the reflective strips at the elbows stay visible as you run; keep coral the only bright colour and everything else dark.", "de": "Den gerafften Saum knapp über der Hüfte enden lassen, damit der senkrechte Silberstreifen am Rücken und die Reflexstreifen an den Ellbogen beim Laufen sichtbar bleiben; Koralle als einzige helle Farbe, alles andere dunkel."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/05/products/01-outer.webp", "alt": "코럴 러닝 셸 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-05.02-top": {"id": "rl-chilly-f35-day-run-20261025-05.02-top", "cat": "top", "name": {"ko": "그래파이트 롱슬리브", "en": "Graphite crew-neck running long sleeve", "de": "Graphitgraues Laufshirt mit Rundhals und langen Ärmeln"}, "note": {"ko": "셸 소매단 밖으로 그래파이트 소매가 손목에 살짝 나오게 입으면 코럴 끝에 어두운 테두리가 생겨요. 지퍼나 프린트 없는 크루넥이라 셸 안에서 깔끔하게 정리돼요.", "en": "Let the graphite sleeves show a little past the shell cuffs to frame the coral with a dark edge; the plain crew neck, with no zip or print, sits neatly inside the shell.", "de": "Die graphitgrauen Ärmel etwas unter den Shell-Bündchen hervorschauen lassen, so bekommt die Koralle einen dunklen Rand; der schlichte Rundhals ohne Reißverschluss oder Print sitzt ordentlich in der Shell."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/05/products/02-top.webp", "alt": "그래파이트 롱슬리브 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-05.03-bottom": {"id": "rl-chilly-f35-day-run-20261025-05.03-bottom", "cat": "bottom", "name": {"ko": "블랙 리플렉티브 타이츠", "en": "Black reflective running tights", "de": "Schwarze Lauftights mit Reflexstreifen"}, "note": {"ko": "종아리 바깥의 가는 은색 줄이 뒤에서 보이도록 밑단을 발목에 맞춰 곧게 입어요. 매끈한 블랙이 코럴 셸 아래 실루엣을 길게 이어 줘요.", "en": "Wear the hems straight at the ankle so the fine silver strips on the outer calves show from behind; the smooth black draws a long line under the coral shell.", "de": "Die Säume gerade am Knöchel tragen, damit die feinen Silberstreifen an den äußeren Waden von hinten zu sehen sind; das glatte Schwarz zieht unter der korallenroten Shell eine lange Linie."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/05/products/03-bottom.webp", "alt": "블랙 리플렉티브 타이츠 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-05.04-socks": {"id": "rl-chilly-f35-day-run-20261025-05.04-socks", "cat": "socks", "name": {"ko": "그레이 러닝 양말", "en": "Grey quarter running socks", "de": "Graue Laufsocken in Quarter-Länge"}, "note": {"ko": "발목뼈를 살짝 덮는 쿼터 길이라 타이츠 밑단과 신발 사이에 그레이가 가늘게 한 줄만 보여요. 높이 끌어올리지 말고 그대로 신어요.", "en": "The quarter length just covers the ankle bone, so only a thin band of grey shows between the tights hem and the shoe; wear them as they are rather than pulling them high.", "de": "Die Quarter-Länge bedeckt knapp den Knöchel, sodass zwischen Tightssaum und Schuh nur ein schmales graues Band sichtbar ist; einfach so tragen, nicht hochziehen."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/05/products/04-socks.webp", "alt": "그레이 러닝 양말 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}, "rl-chilly-f35-day-run-20261025-05.05-shoes": {"id": "rl-chilly-f35-day-run-20261025-05.05-shoes", "cat": "shoes", "name": {"ko": "다크 그레이 러닝화", "en": "Dark grey mesh running shoes", "de": "Dunkelgraue Laufschuhe aus Mesh"}, "note": {"ko": "다크 그레이 메시와 검은 뒤꿈치 오버레이가 블랙 타이츠와 이어져 발끝까지 어둡게 정리돼요. 라이트 그레이 미드솔이 걸음마다 얇은 밝은 선을 남겨요.", "en": "Dark grey mesh and black heel overlays continue the black tights right down to the foot; the light grey midsole leaves a thin bright line with every step.", "de": "Dunkelgraues Mesh und schwarze Fersenoverlays führen die schwarzen Tights bis zum Fuß weiter; die hellgraue Mittelsohle hinterlässt bei jedem Schritt eine schmale helle Linie."}, "image": "look/berlin-complete/Rain/Light/Chilly/Female/35+/day/running-20261025/05/products/05-shoes.webp", "alt": "다크 그레이 러닝화 — 투명 배경 독립 제품 컷", "bg": "#F3EFE8"}};
